export function formatPrice(p) {
  if (p === null || p === undefined || p === "") return "-";
  const n = Number(p);
  if (Number.isNaN(n)) return "-";
  if (n < 0) return "var";
  if (!Number.isFinite(n)) return "-";
  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/i.exec(n.toString());
  if (!m) return "-";
  const frac = m[2] || "";
  const digits = BigInt(m[1] + frac);
  const e = (m[3] ? parseInt(m[3], 10) : 0) - frac.length + 8;
  let q;
  if (e >= 0) {
    q = digits * 10n ** BigInt(e);
  } else {
    const d = 10n ** BigInt(-e);
    q = digits / d;
    if ((digits % d) * 2n >= d) q += 1n;
  }
  const s = q.toString().padStart(3, "0");
  return "$" + s.slice(0, -2) + "." + s.slice(-2);
}
