/**
 * Tower edge parser.
 *
 * Parses strings of the form:
 *   "from -> to"
 *   "from -> to: label"
 *   "from -> to [kind]"
 *   "from -> to [kind]: label"
 *
 * @param {string} text
 * @returns {{from: string, to: string, kind: string, label?: string}|string}
 *          the parsed edge, or an error message string containing the bad text.
 */

const VALID_KINDS = new Set(['flow', 'call', 'spawn', 'handoff', 'return', 'data']);
const DEFAULT_KIND = 'flow';

// Node ids: letters, digits, '_', '.', '-'
const NODE_ID = /^[A-Za-z0-9_.-]+$/;

function invalid(text) {
  return `Invalid edge: ${text}`;
}

export function parseEdge(text) {
  if (typeof text !== 'string') {
    return `Invalid edge: ${String(text)}`;
  }

  // 1. Split off the "from" side at the first "->".
  //    Node ids cannot contain '-' followed by '>', so the first arrow is
  //    always the separator (a later "->" can only live inside the label).
  const arrow = text.indexOf('->');
  if (arrow === -1) {
    return invalid(text);
  }

  const from = text.slice(0, arrow).trim();
  if (!NODE_ID.test(from)) {
    return invalid(text);
  }

  const rest = text.slice(arrow + 2);

  // 2. Split off the label at the first colon. Everything after it (trimmed)
  //    is the label and may itself contain colons.
  let head = rest;
  let label;
  const colon = rest.indexOf(':');
  if (colon !== -1) {
    head = rest.slice(0, colon);
    const trimmed = rest.slice(colon + 1).trim();
    label = trimmed === '' ? undefined : trimmed;
  }

  // 3. The remaining head is "to" with an optional "[kind]" suffix.
  let to = head.trim();
  let kind = DEFAULT_KIND;

  const open = to.indexOf('[');
  if (open !== -1) {
    const close = to.indexOf(']', open);
    if (close === -1) {
      return invalid(text);
    }
    const target = to.slice(0, open).trim();
    const kindToken = to.slice(open + 1, close).trim();
    const trailing = to.slice(close + 1).trim();
    if (trailing !== '') {
      return invalid(text);
    }
    to = target;
    kind = kindToken;
  }

  // 4. Validate the node ids.
  if (!NODE_ID.test(to)) {
    return invalid(text);
  }

  // 5. Validate the kind.
  if (!VALID_KINDS.has(kind)) {
    return `Invalid edge: ${text} (unknown kind "${kind}")`;
  }

  return { from, to, kind, label };
}
