/**
 * Format a per-token USD price as a per-million-token dollar string.
 *
 * @param {string|number|null|undefined} p
 * @returns {string} e.g. "$0.30", "$2.50", "$0.00", "var", "-"
 */
export function formatPrice(p) {
  if (p === null || p === undefined || p === "") return "-";

  const n = typeof p === "number" ? p : Number(p);
  if (!Number.isFinite(n)) return "-";

  // A negative price signals a variable/unknown rate.
  if (n < 0) return "var";

  // Convert per-token price to per-million-token price.
  const perMillion = n * 1e6;

  // Guard against floating point under-shoot (e.g. 2.4999999999999996).
  const scaled = perMillion * 100;
  const cents = Math.round(scaled + Number.EPSILON * Math.abs(scaled));
  const dollars = cents / 100;

  return "$" + dollars.toFixed(2);
}

export default formatPrice;
