export function formatPrice(p) {
  if (p === null || p === undefined || p === "") return "-";

  const s = String(p).trim();
  if (s === "") return "-";

  const neg = s.startsWith("-");
  const abs = neg ? s.slice(1) : s;

  if (!/^\d*\.?\d*$/.test(abs) || abs === "" || abs === ".") return "-";

  // Shift decimal point 6 places right (per token -> per million tokens)
  let digits = abs.replace(".", "");
  const pointPos = abs.indexOf(".");
  const decPlaces = pointPos === -1 ? 0 : abs.length - pointPos - 1;
  const shift = 6 - decPlaces;
  if (shift > 0) digits += "0".repeat(shift);
  else if (shift < 0) {
    const cut = digits.length + shift;
    digits = digits.slice(0, Math.max(cut, 0)) || "0";
  }

  // Round to 2 decimals: scale by 100, round half up
  const scaled = BigInt(digits) * 100n;
  const million = 1000000n;
  let cents = scaled / million;
  const rem = scaled % million;
  if (rem * 2n >= million) cents += 1n;

  const whole = cents / 100n;
  const frac = (cents % 100n).toString().padStart(2, "0");

  return (neg && cents !== 0n ? "-$" : "$") + whole.toString() + "." + frac;
}
