  const shifted = Number(n.toString().includes("e") ? n.toExponential() : n.toString());
  // Use exponent notation to shift decimal point: "<n>e6"
  const str = shifted.toString();
  let millions;
  if (str.includes("e")) {
    const [m, e] = str.split("e");
    millions = Number(m + "e" + (Number(e) + 6));
  } else {
    millions = Number(str + "e6");
  }
  // Round half up to 2 decimals using exponent shifting
  const [m2, e2 = "0"] = millions.toString().split("e");
  const cents = Math.round(Number(m2 + "e" + (Number(e2) + 2)));
  const out = Number(cents + "e-2");
  return "$" + out.toFixed(2);
}
