 * Parses a tower-file edge declaration of the form:
 *
 *   from -> to
 *   from -> to: label
 *   from -> to [kind]
 *   from -> to [kind]: label
 *
 * Returns `{ from, to, kind, label }` on success, or an error *string*
 * (never a thrown exception) when the text does not parse or the kind is
 * not one of the valid kinds.
 */

const VALID_KINDS = new Set([
  'flow',
  'call',
  'spawn',
  'handoff',
  'return',
  'data',
]);

const DEFAULT_KIND = 'flow';

// from  ->  to  [kind]  :  label
//  - ids: letters, digits, "_", "." and "-"
//  - whitespace around every part is insignificant
//  - the label is "everything after the first colon", so it may contain
//    colons (and anything else, including newlines).
const EDGE_RE =
  /^([A-Za-z0-9_.-]+)\s*->\s*([A-Za-z0-9_.-]+)\s*(?:\[([^\]]*)\])?\s*(?::([\s\S]*))?$/;

export function parseEdge(text) {
  if (typeof text !== 'string') {
    return `Invalid edge: expected a string, got ${String(text)}`;
  }

